<map version="1.0.1">
<node TEXT="事实-读书笔记"><node TEXT="十大情绪化本能"><node TEXT="一分为二"><node TEXT="定义：把事物分成对立的两类，如富有和贫穷，发达国家，发展中国家"></node><node TEXT="如何防范"><node TEXT="不只看平均数"></node><node TEXT="不只比较极端情况"></node><node TEXT="不俯视"><node TEXT="发展中国家一样穷"></node></node></node><node TEXT="其实就是统计数据分析，如何从数据中更准确的看出对象的真实情况"></node></node><node TEXT="负面思维"><node TEXT="体现"><node TEXT="对过去错误的记忆"><node TEXT="记忆里的事物比实际更坏"></node></node><node TEXT="媒体对负面新闻的选择性报道"></node><node TEXT="感性而非理性"><node TEXT="我们认为，只要坏的事情发生，就不该认为世界在变好"></node></node></node><node TEXT="如何防范"><node TEXT="区分状态和趋势，认识到事情可以同时是不好的，但在变好"></node><node TEXT="好消息不是新闻"></node><node TEXT="循序渐进不是新闻"></node><node TEXT="更多的坏消息不意味着更多的坏事情"></node><node TEXT="警惕被美化过的历史（个人和国家都会刻意美化自己的历史）"></node></node></node><node TEXT="直线思维"><node TEXT="简单地认为事物的发展规律会继续延续下去"></node><node TEXT="例子"><node TEXT="人口增长，根据曲线图，人类人口还是爆发性增长，但实际是逐渐变缓，等待下一次科技革命后再大幅增长"></node><node TEXT="小孩的身高初始很快，后越来越慢，直到成年后不再增加"></node></node></node><node TEXT="恐惧本能"><node TEXT="注意力的过滤机制"><node TEXT="信息过载"></node><node TEXT="倾向于接受一些夸张的信息"></node></node><node TEXT="恐惧的本能扭曲了我们的关注点"><node TEXT="比如飞机，其出事的概率小于任何其他交通工具，但飞机出事就是大事，让我们认为飞机更加危险"></node><node TEXT="实际上我们所熟知的巨大灾难的死亡人数已经是非常小了"></node></node><node TEXT="当我们陷入恐惧的时候，就无法看到现实"><node TEXT="比如非典很大一批人是早期蜂拥去医院排队候诊被交叉传染的"></node><node TEXT="新冠肺炎出现的物资抢购，正常的购买食物是不会短缺的，但恐惧导致囤物资，进而物资短缺，进而逼迫所有人跟着囤物资，物资更加短缺的恶性循环"></node></node></node><node TEXT="规模错觉"><node TEXT="人们很容易注意局部而忽略整体"><node TEXT="总是注意到一个单一的数字而误判他的重要性"></node><node TEXT="媒体迎合这种错觉，夸大单一事件、事实或数字的重要性"></node><node TEXT="把有限的注意力和资源集中到看得见的受害者和个体上"></node></node><node TEXT="如何防范"><node TEXT="对比和比例"><node TEXT="面对单一数字"><node TEXT="和其他什么数字作比较"></node><node TEXT="历史数据如何"></node><node TEXT="对应的比例呢"></node></node></node><node TEXT="二八原则"><node TEXT="面对一系列事物，找到最大的几项并做深入分析"></node></node></node></node><node TEXT="以偏概全"><node TEXT="表现"><node TEXT="错误的归纳"><node TEXT="一分为二把世界分成我们和他们，以偏概全认为他们是一样的"></node></node><node TEXT="误导性的以偏概全，极端典型，都是媒体善用的手段"></node></node><node TEXT="如何防范"><node TEXT="质疑分类的方法"><node TEXT="同一类别找不同"></node><node TEXT="不同类别找相同"></node></node><node TEXT="注意大多数"><node TEXT="51%和99%是不一样的，但都是大多数"></node></node><node TEXT="注意极端案例"><node TEXT="活灵活现的图片会留下深刻的印象，但不一定是普遍现象"></node></node><node TEXT="不要假设别人是傻瓜"><node TEXT="发现奇特现象，应保持谦卑和好奇，探究背后的道理"></node></node></node></node><node TEXT="命中注定"><node TEXT="认为一些事物的内在属性将决定其命运，比如国家，宗教或者文化"></node><node TEXT="但世界是持续变化的"></node><node TEXT="例子"><node TEXT="生育和宗教无关，只是贫困的妇女会生更多的孩子"></node><node TEXT="通常认为伊斯兰教的妇女生育更多"></node></node><node TEXT="如何防范"><node TEXT="不要忽视微小的变化"><node TEXT="每年增长1%，七十年翻一倍"></node></node><node TEXT="不断更新你的知识"></node></node></node><node TEXT="单一视角"><node TEXT="表现"><node TEXT="倾向于认为所有的问题都有单一的原因和单一的解决方案"></node></node><node TEXT="例子"><node TEXT="当下媒体中认为民主是所有问题的解决方案"></node></node><node TEXT="如何防范"><node TEXT="有限的经验"><node TEXT="锤子和钉子"><node TEXT="夸大自己专注的问题和解决方案的重要性"></node></node><node TEXT="多和不同的人交流，发现不足和局限性"></node></node><node TEXT="关注数字，但不仅仅是数字"><node TEXT="目的是为了认识现实，数字只是媒介"></node><node TEXT="交叉验证"><node TEXT="比如GDP的统计，可以人为夸大，但不能和其他表现验证了"></node></node></node><node TEXT="当心简单的想法和简单的解决方案"><node TEXT="事物是复杂的"></node><node TEXT="具体事情具体分析"></node></node></node></node><node TEXT="归咎他人"><node TEXT="表现"><node TEXT="当坏事情发生后，总试图找一个清晰而简单的理由去责怪其他人"></node><node TEXT="会夸大个人或者某个团体的重要性（责怪的对象），从而忽略了对真相的理解"></node></node><node TEXT="如何防范"><node TEXT="目标是寻找原因，而不是寻找坏人"></node><node TEXT="不应将坏的结果归咎于某个人，而应检查整个系统"></node></node></node><node TEXT="情急生乱"><node TEXT="表现"><node TEXT="现在行动，否则你将永远失去机会"><node TEXT="销售员的推销话术"></node></node><node TEXT="你必须立刻做决定，立刻行动！"></node></node><node TEXT="如何防范"><node TEXT="坚持了解基础数据"><node TEXT="警惕相关但不准确的数据"></node><node TEXT="只有相关且准确的数据才有用"></node></node><node TEXT="小心过激的行动"><node TEXT="通常循序渐进的方案，总会优于大刀阔斧的行动"></node></node></node></node></node><node TEXT="总结"><node TEXT="克服情绪化本能"><node TEXT=""></node></node><node TEXT="实事求是"></node></node></node>
</map>